def copy_resumes_to_candidate(apps, schema_editor):
    """Copy existing resumes from Application to Candidate.
    For candidates with multiple applications having a resume, take the most recent one."""
    Application = apps.get_model('hr_recruitment', 'Application')
    Candidate = apps.get_model('hr_recruitment', 'Candidate')
    db_alias = schema_editor.connection.alias

    for candidate in Candidate.objects.using(db_alias).all():
        # Get the most recent application with a resume for this candidate
        app_with_resume = (
            Application.objects.using(db_alias)
            .filter(candidate=candidate, resume__isnull=False)
            .order_by('-applied_at')
            .first()
        )
        if app_with_resume and app_with_resume.resume:
            candidate.resume = app_with_resume.resume
            candidate.save(update_fields=['resume'])


